package com.example.com.englishai.backend.infrastructure.security; import org.springframework.context.annotation.*; import org.springframework.beans.factory.annotation.Value; import java.time.Duration; import com.example.com.englishai.backend.application.ports.*;
@Configuration public class PasswordResetCodeConfig {@Bean PasswordResetCodeGenerator passwordResetCodeGenerator(){return new SecurePasswordResetCodeGenerator();}@Bean PasswordResetCodeHasher passwordResetCodeHasher(@Value("${SECURITY_PASSWORD_RESET_CODE_HASH_SECRET:}")String s){return new HmacPasswordResetCodeHasher(s);}@Bean Duration passwordResetCodeExpiration(@Value("${SECURITY_PASSWORD_RESET_CODE_EXPIRATION_SECONDS:600}")long s){if(s<=0)throw new IllegalArgumentException("Password reset expiration must be positive");return Duration.ofSeconds(s);}@Bean Integer passwordResetMaxAttempts(@Value("${SECURITY_PASSWORD_RESET_MAX_ATTEMPTS:5}")int n){if(n<=0)throw new IllegalArgumentException("Password reset max attempts must be positive");return n;}}
